   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="它由宝石和黄金打造，没人知道里面装着些什么，伊南姆家族耗费数十年都没能把它打开，直到二十多年前它被“乌鸦＆白鸽”盗走。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_204.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="按照这对盗贼的作风，被盗走的东西本来应该很快被归还，但直到他们对外宣布金盆洗手，潘多拉之盒都没能回归伊南姆家的宝库，再后来随着伊南姆家族的覆灭，这件宝物的去向就成了一个谜。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_204.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
